+describe('retry and backoff behavior', () => {
+  beforeEach(() => {
+    resetTypesafeBreaker();
+    resetTypesafeLimiter();
+    process.env.TYPESAFE_API_KEY = 'test-key';
+  });
+
+  afterEach(() => {
+    delete process.env.TYPESAFE_API_KEY;
+    vi.useRealTimers();
+  });
+
+  it('retries on HTTP 429 (rate limited) instead of breaking immediately', async () => {
+    const failFetch = vi.fn().mockResolvedValue({ ok: false, status: 429 }) as unknown as typeof fetch;
+    const client = new TypeSafeClient(failFetch);
+
+    await expect(client.systemOne({}, {}, { retries: 2 })).rejects.toThrow('TYPESAFE_FAILED');
+
+    // 429 is a transient error that should be retried: initial + 2 retries = 3 calls.
+    // Mutant 2 (`!== 429 ||` instead of `!== 429 &&`) breaks after the first call → only 1 invocation.
+    expect(failFetch).toHaveBeenCalledTimes(3);
+  });
+
+  it('applies exponential backoff between attempts (400 ms then 800 ms)', async () => {
+    vi.useFakeTimers();
+    const failFetch = vi.fn().mockResolvedValue({ ok: false, status: 500 }) as unknown as typeof fetch;
+    const client = new TypeSafeClient(failFetch);
+
+    let rejected = false;
+    const promise = client.systemOne({}, {}, { retries: 2 }).catch(() => { rejected = true; });
+
+    // Flush microtasks so the first fetch resolves and the 400 ms timer is scheduled.
+    await vi.advanceTimersByTimeAsync(0);
+    expect(failFetch).toHaveBeenCalledTimes(1);
+
+    // Advance through the first backoff window (400 ms) → second attempt fires.
+    // Correct code: waits 400*2^0=400 before retry 1.
+    // Mutant 1 (`attempt >= retries`): no wait before any of the first two retries,
+    //   so all three fetches would already have fired by now.
+    await vi.advanceTimersByTimeAsync(400);
+    expect(failFetch).toHaveBeenCalledTimes(2);
+
+    // Advance through the second backoff window (800 ms) → third and final attempt.
+    await vi.advanceTimersByTimeAsync(800);
+    expect(failFetch).toHaveBeenCalledTimes(3);
+
+    // No further backoff after the last attempt; the call rejects.
+    await promise;
+    expect(rejected).toBe(true);
+  });
+});

